        let skip = first_w
            + unit_len
            + GAP.len()
            + last_w
            + unit_len
            + GAP.len()
            + range_w
            + unit_len
            + GAP.len()
            + count_w;
        println!(
            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
            "mean",
            "",
            fmt_commas_f64(conv_f(hist_mean), 0),
        );
        println!(
            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
            "stdev",
            "",
            fmt_commas_f64(conv_f(self.hist.stdev()), 0),
        );

